return [
  {
    json: {
      response: "ไม่พบ lineID นี้ กรุณาพิมลงทะเบียนแล้วตามด้วยรหัสพนักงานก่อนค่ะ"
    }
  }
];

const params = $json;
const now = new Date();
const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());

function smartParseDate(dateStr) {
    if (!dateStr) return null;
    let d = new Date(dateStr);
    if (d < today && d.getMonth() < today.getMonth()) {
        d.setFullYear(d.getFullYear() + 1);
    }
    return d;
}

let startDate = smartParseDate(params.start_date);
let endDate = smartParseDate(params.end_date);

if (!endDate && startDate) endDate = new Date(startDate);
if (endDate < startDate) {
   endDate.setFullYear(endDate.getFullYear() + 1);
}

let isValid = true;
let errorMsg = "";

if (startDate.getTime() < today.getTime()) {
    isValid = false;
    errorMsg = `ไม่สามารถทำรายการย้อนหลังได้ครับ (คุณเลือกวันที่ ${params.start_date})`;
}

function toISODate(d) {
    const year = d.getFullYear();
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
}

return {
    json: {
        ...params,
        start_date: toISODate(startDate),
        end_date: toISODate(endDate),
        days: params.days,
        is_valid: isValid,
        error_message: errorMsg
    }
};

const errorMsg = $('Convert Year and Valid Date').first().json.error_message;

return [
  {
    json: {
      response: `ทำรายการไม่สำเร็จ: ${errorMsg}` 
    }
  }
];

const triggerParams = $('Convert Year and Valid Date').first().json;
const employeeData = $('Get Employee').first().json;

function formatThaiDate(dateString) {
  if (!dateString) return "";
  const parts = dateString.split('-');
  if (parts.length !== 3) return dateString;
  const yearAD = parseInt(parts[0]);
  const month = parts[1];
  const day = parts[2];
  const yearBE = yearAD + 543;
  return `${day}/${month}/${yearBE}`;
}

const days = parseFloat(triggerParams.days);
const leaveType = triggerParams.leave_type;
const leaveTypeThai = leaveType === 'sick' ? 'ลาป่วย' : 'ลากิจ/พักร้อน';
const startDateThai = formatThaiDate(triggerParams.start_date);
const endDateThai = formatThaiDate(triggerParams.end_date);
const startTime = triggerParams.start_time;
const endTime = triggerParams.end_time;
const reason = triggerParams.reason || '-';

const currentBalance = leaveType === 'sick' 
  ? parseFloat(employeeData.sick_balance) 
  : parseFloat(employeeData.annual_balance);
const remainingBalance = currentBalance - days;

if (remainingBalance < 0) {
  return [
    {
      json: {
        response: `ไม่สามารถ${leaveTypeThai}ได้ เนื่องจากมีวันลาไม่เพียงพอ วันลาของคุณ ${employeeData.firstname} เหลือจำนวน ${currentBalance} วัน`,
        sendFlex: false
      }
    }
  ];
}

let timeInfo = "";
if (startTime && startTime !== "00:00:00" && startTime !== "00:00" && startTime !== "") {
    const sTime = startTime.substring(0, 5);
    const eTime = endTime ? endTime.substring(0, 5) : "";
    timeInfo = ` (เวลา ${sTime} - ${eTime})`;
}

let dateMessage = "";
if (triggerParams.start_date === triggerParams.end_date) {
    dateMessage = `${startDateThai}${timeInfo}`;
} else {
    dateMessage = `${startDateThai} ถึง ${endDateThai}${timeInfo}`;
}

const confirmationId = `leave_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

const confirmData = JSON.stringify({
  action: 'confirm_leave',
  id: confirmationId,
  lineID: triggerParams.lineID,
  leave_type: leaveType,
  start_date: triggerParams.start_date,
  end_date: triggerParams.end_date,
  start_time: startTime || '',
  end_time: endTime || '',
  days: days,
  reason: reason
});

const cancelData = JSON.stringify({
  action: 'cancel_leave',
  id: confirmationId
});

const flexMessage = {
  type: "flex",
  altText: `ยืนยันการ${leaveTypeThai}`,
  contents: {
    type: "bubble",
    size: "mega",
    header: {
      type: "box",
      layout: "vertical",
      contents: [
        {
          type: "text",
          text: `ยืนยันการ${leaveTypeThai}`,
          weight: "bold",
          size: "xl",
          color: "#ffffff"
        }
      ],
      backgroundColor: leaveType === 'sick' ? "#FF6B6B" : "#4ECDC4",
      paddingAll: "20px"
    },
    body: {
      type: "box",
      layout: "vertical",
      contents: [
        {
          type: "box",
          layout: "horizontal",
          contents: [
            { type: "text", text: "ชื่อพนักงาน", size: "sm", color: "#555555", flex: 0 },
            { type: "text", text: `${employeeData.firstname} ${employeeData.lastname}`, size: "sm", color: "#111111", align: "end", weight: "bold" }
          ],
          margin: "md"
        },
        {
          type: "box",
          layout: "horizontal",
          contents: [
            { type: "text", text: "ประเภทการลา", size: "sm", color: "#555555", flex: 0 },
            { type: "text", text: leaveTypeThai, size: "sm", color: "#111111", align: "end", weight: "bold" }
          ],
          margin: "md"
        },
        {
          type: "box",
          layout: "horizontal",
          contents: [
            { type: "text", text: "วันที่ลา", size: "sm", color: "#555555", flex: 0 },
            { type: "text", text: dateMessage, size: "sm", color: "#111111", align: "end", weight: "bold" }
          ],
          margin: "md"
        },
        {
          type: "box",
          layout: "horizontal",
          contents: [
            { type: "text", text: "จำนวนวัน", size: "sm", color: "#555555", flex: 0 },
            { type: "text", text: `${days} วัน`, size: "sm", color: "#111111", align: "end", weight: "bold" }
          ],
          margin: "md"
        },
        {
          type: "box",
          layout: "horizontal",
          contents: [
            { type: "text", text: "เหตุผล", size: "sm", color: "#555555", flex: 0 },
            { type: "text", text: reason, size: "sm", color: "#111111", align: "end", weight: "bold", wrap: true }
          ],
          margin: "md"
        },
        { type: "separator", margin: "xl" },
        {
          type: "box",
          layout: "horizontal",
          contents: [
            { type: "text", text: "ยอดคงเหลือหลังลา", size: "sm", color: "#555555", flex: 0 },
            { type: "text", text: `${remainingBalance} วัน`, size: "sm", color: leaveType === 'sick' ? "#FF6B6B" : "#4ECDC4", align: "end", weight: "bold" }
          ],
          margin: "xl"
        }
      ],
      paddingAll: "20px"
    },
    footer: {
      type: "box",
      layout: "horizontal",
      spacing: "sm",
      contents: [
        {
          type: "button",
          style: "primary",
          height: "sm",
          action: { type: "postback", label: "✓ ยืนยัน", data: confirmData, displayText: "ยืนยันการลา" },
          color: "#4ECDC4"
        },
        {
          type: "button",
          style: "secondary",
          height: "sm",
          action: { type: "postback", label: "✗ ยกเลิก", data: cancelData, displayText: "ยกเลิกการลา" }
        }
      ],
      flex: 0,
      paddingAll: "20px"
    }
  }
};

return [
  {
    json: {
      response: "กรุณากดยืนยันหรือยกเลิกในข้อความด้านล่างค่ะ",
      flexMessage: flexMessage,
      sendFlex: true,
      lineID: triggerParams.lineID
    }
  }
];
